// W0-05a: fetch + verify + publication-state rules for demo packages. The wire
// shape and the registry live in `./schema.ts`; this module decides what a
// screen may render from a package. It fails closed on every path: an invalid,
// hash-mismatched, corrupt, unapproved, superseded or revoked package never
// yields playable media, and a missing or unconfigured mirror yields the locked
// `footage-pending` state — never a network guess, never a stand-in clip.
//
// The package is served from a same-origin mirror at
// `<mirrorUrl>/demos/<scenarioId>.json`, regenerated by L9 at build time. The
// mirror URL comes from config alone; there is no default host and no second
// fetch path for the same endpoint. Every request carries a deadline (see
// `fetchTimeoutMs` and `DEFAULT_FETCH_TIMEOUT_MS`), so a hung mirror resolves
// as the offline branch instead of holding a screen forever.
//
// What the content hash is, exactly: corruption detection and truncation
// detection, and nothing more. The hash travels inside the body it covers, so
// any writer can produce a matching hash — it is not a signature and this
// client makes no authenticity claim. The mirror host is the trust anchor. The
// hash covers the body serialized in one canonical form: object keys sorted at
// every level, arrays in their wire order, finite numbers as `JSON.stringify`
// writes them (shortest round-trip, so `1e3` and `1000` both hash as `1000`),
// and the `contentHash` key removed — a digest cannot cover itself.
//
// Cache contract: entries store the raw body so every read re-verifies the
// hash and re-runs the full parse and publication gates — a cached package can
// only ever play through the same rules a fresh fetch passes. `markForPurge`
// condemns the entry's cached media: a marked entry never presents playable
// media, while deleting the cached media files is the host's job and the small
// record stays so an offline screen can keep saying why playback stopped. An
// invalid network body marks the entry for purge and is never written — a
// corrupt or hostile update must not leave stale approved media playable.
// `put` clears the mark, so a freshly approved package plays again.

import { isHttpsUrl, isRfc3339 } from '../release/schema';
import {
  isRecord,
  isScenarioId,
  parseDemoPackage,
  type DemoInteractive,
  type DemoPackage,
  type DemoProblem,
  type DemoRendition,
  type ScenarioRegistry,
  type ScenarioRegistryRow,
} from './schema';

const HEX64 = /^[0-9a-f]{64}$/;

/** Default deadline for one bounded mirror request, in milliseconds. */
const DEFAULT_FETCH_TIMEOUT_MS = 10_000;

/** SHA-256 over UTF-8 bytes, via the platform's Web Crypto (no node: imports). */
async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  let hex = '';
  for (const byte of new Uint8Array(digest)) hex += byte.toString(16).padStart(2, '0');
  return hex;
}

/**
 * The canonical form the content hash covers: object keys sorted
 * lexicographically at every level, arrays in their wire order, and scalars
 * serialized as `JSON.stringify` writes them — for finite numbers that is the
 * shortest round-trip form, so `1e3` and `1000` hash the same. This removes
 * the digest's accidental dependence on key order and number spelling.
 */
function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map((item) => canonicalJson(item)).join(',')}]`;
  if (isRecord(value)) {
    const keys = Object.keys(value).sort();
    return `{${keys.map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  const scalar = JSON.stringify(value);
  return scalar === undefined ? 'null' : scalar;
}

/** Why a package was refused, on top of the schema's own problem codes. */
export type InvalidReason =
  | DemoProblem
  | 'hash-mismatch'
  | 'captions-required'
  | 'approval-incomplete'
  | 'scenario-mismatch';

/** The media an approved package may hand a player. */
export type DemoMedia = {
  renditions: readonly DemoRendition[];
  posterUrl: string;
  interactive: DemoInteractive | null;
};

/**
 * The presentation union W0-05b's player renders. Exact shapes matter: an
 * `invalid`, `footage-pending` or `superseded` state carries no URL a screen
 * could turn into playback, and `revoked` carries only the transcript.
 */
export type DemoPresentation =
  | {
      state: 'playable';
      scenarioId: string;
      packageRevision: string;
      sourceRevision: string;
      contentHash: string;
      source: 'network' | 'cache';
      fetchedAt: number;
      media: DemoMedia;
      captionsUrl: string;
      transcriptUrl: string;
    }
  | { state: 'footage-pending'; reason: 'footage-pending' }
  | { state: 'superseded'; reason: 'superseded' }
  | { state: 'revoked'; reason: 'revoked'; transcriptUrl: string | null; purgeCached: true }
  | { state: 'invalid'; reason: InvalidReason };

export type CachedDemo = {
  package: DemoPackage;
  /** The raw body exactly as fetched, so a cache read re-verifies the hash. */
  rawText: string;
  fetchedAt: number;
};

export type DemoCache = {
  get(scenarioId: string): CachedDemo | undefined;
  /** Stores a verified entry — and clears any purge mark: a fresh approved package plays again. */
  put(scenarioId: string, entry: CachedDemo): void;
  /** Marks the entry's cached media for deletion; the host performs the purge. */
  markForPurge(scenarioId: string): void;
  /** Whether the entry's cached media is condemned; a marked entry never plays. */
  isMarkedForPurge(scenarioId: string): boolean;
};

/**
 * An in-memory cache for hosts without one. Purged entries keep their record
 * (so an offline screen can still explain a revocation) but are flagged via
 * `isMarkedForPurge`; `put` clears the flag for that scenario.
 */
export function createMemoryDemoCache(): DemoCache {
  const entries = new Map<string, CachedDemo>();
  const purged = new Set<string>();
  return {
    get: (scenarioId) => entries.get(scenarioId),
    put: (scenarioId, entry) => {
      entries.set(scenarioId, entry);
      // A freshly verified, freshly approved entry re-arms playback: the
      // previous purge mark no longer describes this package.
      purged.delete(scenarioId);
    },
    markForPurge: (scenarioId) => {
      purged.add(scenarioId);
    },
    isMarkedForPurge: (scenarioId) => purged.has(scenarioId),
  };
}

/** The one request shape this client makes; injectable for tests and SSR. */
export type FetchLike = (
  url: string,
  init?: { signal?: AbortSignal },
) => Promise<{
  ok: boolean;
  status: number;
  text: () => Promise<string>;
}>;

export type DemoResolverConfig = {
  /**
   * Absolute https origin of the same-origin mirror — no smuggled credentials,
   * no query, no fragment. Absent/unsafe → footage-pending, no fetch.
   */
  mirrorUrl?: string;
  fetchImpl?: FetchLike;
  now?: () => number;
  cache?: DemoCache;
  /** Deadline for one mirror request, in ms; defaults to DEFAULT_FETCH_TIMEOUT_MS. */
  fetchTimeoutMs?: number;
};

export type DemoResolver = ReturnType<typeof createDemoResolver>;

/**
 * A mirror must be a bare https origin: `isHttpsUrl` (the release client's
 * rule) proves the scheme and that no credential is smuggled in, and a query
 * or fragment is refused like every package URL's — both end up in a cache and
 * neither belongs in a mirror address.
 */
function isMirrorOrigin(value: string): boolean {
  if (!isHttpsUrl(value)) return false;
  try {
    const url = new URL(value);
    return url.search === '' && url.hash === '';
  } catch {
    return false;
  }
}

export function createDemoResolver(config: DemoResolverConfig = {}) {
  const rawMirror =
    typeof config.mirrorUrl === 'string' ? config.mirrorUrl.trim().replace(/\/+$/, '') : '';
  // A mirror that is not a bare https origin is a configuration error, and the
  // answer to a configuration error is footage-pending — never a fetch.
  const mirrorUrl = isMirrorOrigin(rawMirror) ? rawMirror : null;
  const fetchImpl: FetchLike = config.fetchImpl ?? ((url, init) => fetch(url, init));
  const now = config.now ?? (() => Date.now());
  const cache = config.cache ?? createMemoryDemoCache();
  const fetchTimeoutMs =
    typeof config.fetchTimeoutMs === 'number' &&
    Number.isFinite(config.fetchTimeoutMs) &&
    config.fetchTimeoutMs > 0
      ? config.fetchTimeoutMs
      : DEFAULT_FETCH_TIMEOUT_MS;
  const footagePending: DemoPresentation = { state: 'footage-pending', reason: 'footage-pending' };

  type FetchOutcome =
    | { kind: 'unreachable' }
    | { kind: 'no-body' }
    | { kind: 'body'; rawText: string };

  /**
   * One bounded request: the deadline covers the fetch and the read, so a
   * stalled mirror cannot hold a screen past `fetchTimeoutMs`. A timeout
   * resolves as the offline branch — the cache, then footage-pending.
   */
  async function fetchBounded(scenarioId: string): Promise<FetchOutcome> {
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const deadline = new Promise<FetchOutcome>((resolveDeadline) => {
      timer = setTimeout(() => {
        controller.abort();
        resolveDeadline({ kind: 'unreachable' });
      }, fetchTimeoutMs);
    });
    const request: Promise<FetchOutcome> = (async () => {
      const response = await fetchImpl(`${mirrorUrl}/demos/${scenarioId}.json`, {
        signal: controller.signal,
      });
      if (!response.ok) return { kind: 'no-body' };
      return { kind: 'body', rawText: await response.text() };
    })();
    try {
      return await Promise.race([request, deadline]);
    } catch {
      return { kind: 'unreachable' };
    } finally {
      if (timer !== undefined) clearTimeout(timer);
    }
  }

  /** Hash gate → parse gate → mirror-label gate, in that order. */
  async function verified(
    rawText: string,
    scenarioId: string,
  ): Promise<{ package: DemoPackage } | { problem: InvalidReason }> {
    let json: unknown;
    try {
      json = JSON.parse(rawText);
    } catch {
      return { problem: 'not-an-object' };
    }
    if (
      isRecord(json) &&
      typeof json.contentHash === 'string' &&
      HEX64.test(json.contentHash.trim().toLowerCase())
    ) {
      // The hash covers the body in canonical form with its own key removed —
      // a digest cannot cover itself. It is corruption detection and truncation
      // detection only: the hash travels inside the body it covers, so any
      // writer can produce a matching one. The mirror host is the trust
      // anchor; this client makes no authenticity claim.
      const rest: Record<string, unknown> = { ...json };
      delete rest.contentHash;
      if ((await sha256Hex(canonicalJson(rest))) !== json.contentHash.trim().toLowerCase()) {
        return { problem: 'hash-mismatch' };
      }
    }
    const parsed = parseDemoPackage(json);
    if ('problem' in parsed) return { problem: parsed.problem };
    // The mirror labels the file by path; the body must agree with the label.
    if (parsed.package.scenarioId !== scenarioId) return { problem: 'scenario-mismatch' };
    return { package: parsed.package };
  }

  function present(pkg: DemoPackage, source: 'network' | 'cache', fetchedAt: number): DemoPresentation {
    switch (pkg.publicationState) {
      case 'pending':
        // Footage pending is the honest state for the whole front door today:
        // nothing plays until an approved package exists.
        return footagePending;
      case 'superseded':
        // A superseded package plays only as labelled historical proof and
        // never under the old URL. Nothing in the package tells the front door
        // which surface is the labelled one, so the presentation carries no
        // media at all — a named state a screen can render, and nothing to play.
        return { state: 'superseded', reason: 'superseded' };
      case 'revoked':
        // Playback stops, the transcript stays readable, and whatever the host
        // cached for this scenario is marked for purge.
        cache.markForPurge(pkg.scenarioId);
        return {
          state: 'revoked',
          reason: 'revoked',
          transcriptUrl: pkg.transcriptUrl,
          purgeCached: true,
        };
      case 'approved': {
        if (pkg.captionsUrl === null || pkg.transcriptUrl === null) {
          // Half-rendered accessibility is not accessibility: captions and the
          // transcript ship together or the package does not play.
          return { state: 'invalid', reason: 'captions-required' };
        }
        if (
          pkg.approval.watchedComplete !== true ||
          pkg.approval.approvedBy === '' ||
          !isRfc3339(pkg.approval.approvedAt)
        ) {
          return { state: 'invalid', reason: 'approval-incomplete' };
        }
        return {
          state: 'playable',
          scenarioId: pkg.scenarioId,
          packageRevision: pkg.packageRevision,
          sourceRevision: pkg.sourceRevision,
          contentHash: pkg.contentHash,
          source,
          fetchedAt,
          media: { renditions: pkg.renditions, posterUrl: pkg.posterUrl, interactive: pkg.interactive },
          captionsUrl: pkg.captionsUrl,
          transcriptUrl: pkg.transcriptUrl,
        };
      }
    }
  }

  /**
   * present() plus the purge gate: a marked scenario's cached media is
   * condemned, so it never presents playable media — a corrupt update cannot
   * leave stale approved media playable while the host deletes the files.
   */
  function presentChecked(
    pkg: DemoPackage,
    source: 'network' | 'cache',
    fetchedAt: number,
    scenarioId: string,
  ): DemoPresentation {
    const presentation = present(pkg, source, fetchedAt);
    if (presentation.state === 'playable' && cache.isMarkedForPurge(scenarioId)) {
      return footagePending;
    }
    return presentation;
  }

  async function resolve(scenarioId: string): Promise<DemoPresentation> {
    // A deep link can carry anything; only a shaped scenario id may reach the
    // mirror, and an unconfigured mirror is answered from what is already
    // known: footage-pending.
    if (!isScenarioId(scenarioId) || mirrorUrl === null) return footagePending;
    const outcome = await fetchBounded(scenarioId);
    if (outcome.kind === 'no-body') {
      // The mirror answered: nothing is published for this scenario today.
      return footagePending;
    }
    const rawText = outcome.kind === 'body' ? outcome.rawText : null;
    if (rawText === null) {
      // Offline or past the deadline: fall through to the cache.
      const entry = cache.get(scenarioId);
      if (entry === undefined) return footagePending;
      const cached = await verified(entry.rawText, scenarioId);
      if ('problem' in cached) return { state: 'invalid', reason: cached.problem };
      return presentChecked(cached.package, 'cache', entry.fetchedAt, scenarioId);
    }
    const verdict = await verified(rawText, scenarioId);
    if ('problem' in verdict) {
      // Rule: an invalid network body condemns whatever this scenario had
      // cached and is never written itself — a corrupt or hostile update must
      // not leave stale approved media playable, and its bytes must not enter
      // the cache. A re-approved package arrives as a valid body and re-arms
      // playback via `put`.
      cache.markForPurge(scenarioId);
      return { state: 'invalid', reason: verdict.problem };
    }
    const entry: CachedDemo = { package: verdict.package, rawText, fetchedAt: now() };
    cache.put(scenarioId, entry);
    return presentChecked(verdict.package, 'network', entry.fetchedAt, scenarioId);
  }

  return { resolve };
}

/**
 * The /engines index is built from the registry alone. A scenario the registry
 * does not name is `unlisted` — still playable by deep link (resolve() never
 * consults the registry), absent from the index rows, and never silently
 * dropped: it comes back named in `unlisted`.
 */
export function buildEnginesIndex(
  registry: ScenarioRegistry,
  scenarioIds: readonly string[],
): { rows: ScenarioRegistryRow[]; unlisted: string[] } {
  const byId = new Map(registry.map((row) => [row.scenarioId, row] as const));
  const rows: ScenarioRegistryRow[] = [];
  const unlisted: string[] = [];
  for (const scenarioId of scenarioIds) {
    const row = byId.get(scenarioId);
    if (row === undefined) {
      unlisted.push(scenarioId);
      continue;
    }
    rows.push({
      scenarioId: row.scenarioId,
      engine: row.engine,
      title: row.title,
      oneLiner: row.oneLiner,
      posterAlt: row.posterAlt,
      order: row.order,
    });
  }
  rows.sort((a, b) => a.order - b.order);
  return { rows, unlisted };
}
